<?php
declare(strict_types=1);namespace App\Controllers;use App\Core\{Csrf,Request,Response,View};use App\Repositories\RtmpRepository;use App\Security\Auth;use App\Services\RtmpService;use Throwable;
final readonly class RtmpController{public function __construct(private View $view,private RtmpRepository $repo,private RtmpService $service,private Csrf $csrf){}public function index(Request $r):void{$this->allow();$this->view->render('rtmp/index',['title'=>'Ingest RTMP','servers'=>$this->repo->servers(),'csrf'=>$this->csrf]);}public function save(Request $r):void{$this->allow();$this->run(fn()=>$this->service->save($r->input));}public function rotate(Request $r):void{$this->allow();$this->run(fn()=>$this->service->rotate($r->int('id')));}public function reveal(Request $r):void{$this->allow();try{Response::json($this->service->reveal($r->int('id')));}catch(Throwable $e){Response::json(['error'=>$e->getMessage()],422);}}private function run(callable $fn):never{try{$fn();Response::redirect('/rtmp');}catch(Throwable $e){http_response_code(422);exit(htmlspecialchars($e->getMessage(),ENT_QUOTES,'UTF-8'));}}private function allow():void{if(!Auth::can('rtmp.manage')){http_response_code(403);exit('Sin permiso');}}}
